from itertools import permutations
faces=['1', '2', '3', '5', '6', '8']
views=[['5', '6', '3'], ['2', '6', '1']]
adj=set()
for v in views:
    for a in v:
        for b in v:
            if a!=b: adj.add(frozenset((a,b)))
sols=set()
for p in permutations(faces):
    pairs=[frozenset((p[0],p[1])),frozenset((p[2],p[3])),frozenset((p[4],p[5]))]
    if any(q in adj for q in pairs): continue
    for q in pairs:
        if '6' in q: sols.add(next(iter(q-{'6'})))
assert len(sols)==1
ans=sols.pop()
opts={'A': '3', 'B': '2', 'C': '8', 'D': '1'}
assert ans==opts['C']
for k,v in opts.items():
    if k!='C': assert ans!=v
